/usr/bin/bash -lc "perl -MIO::Uncompress::Gunzip -e '
use strict; use warnings;
my ("'$fp,$rp)=@ARGV;
my $F=IO::Uncompress::Gunzip->new($fp) or die "open F: $IO::Uncompress::Gunzip::GunzipError'"\\n\";
my "'$R=IO::Uncompress::Gunzip->new($rp) or die "open R: $IO::Uncompress::Gunzip::GunzipError'"\\n\";
sub rec { my ("'$fh)=@_; my @x; for (1..4){ my $l=<$fh>; return if !defined $l && $_==1; die "truncated fastq'"\\n\" if "'!defined $l; chomp $l; push @x,$l; } return @x; }
sub cid { my ($h)=@_; $h =~ s/''^'"\\@//; my ("'$id)=split /'"\\s+/, "'$h; $id =~ s|/[12]$||; return $id; }
my ($n,$bad_id,$bad_len,$bad_n,$bad_q,$minlf,$maxlf,$minlr,$maxlr)=(0,0,0,0,0,10**9,0,10**9,0);
while (1){ my @a=rec($F); my @b=rec($R); last if !@a && !@b; die "record count mismatch'"\\n\" unless @a && @b; "'$n++; $bad_id++ if cid($a[0]) ne cid($b[0]); for my $mate ([$a[1],$a[3],'"\\"'$minlf,'"\\"'$maxlf], [$b[1],$b[3],'"\\"'$minlr,'"\\"'$maxlr]) { my ($s,$q,$minr,$maxr)=@$mate; my $len=length($s); $$minr=$len if $len<$$minr; $$maxr=$len if $len>$$maxr; $bad_len++ if $len < 15; my $ns = ($s =~ tr/Nn//); $bad_n++ if $ns > 5; my $low=0; for my $i (0..length($q)-1){ $low++ if ord(substr($q,$i,1))-33 < 20; } $bad_q++ if $low/$len > 0.40; } }
print "pairs=$n'"\\n\";
print \"id_mismatches="'$bad_id'"\\n\";
print \"length_fail_mates="'$bad_len'"\\n\";
print \"n_fail_mates="'$bad_n'"\\n\";
print \"low_quality_fail_mates="'$bad_q'"\\n\";
print \"forward_length_range="'$minlf-$maxlf'"\\n\";
print \"reverse_length_range="'$minlr-$maxlr'"\\n\";
' /workspace/final_answer/trimmed_forward.fastqsanger.gz /workspace/final_answer/trimmed_reverse.fastqsanger.gz"

